const doc = $input.first().json;
const mime = String(doc.mime_type ?? '').toLowerCase();
const allowed = ['image/jpeg', 'image/png'];
const base64 = String(doc.document_base64 ?? '');
const config = {
  provider: 'nvidia_nim',
  endpoint: 'https://integrate.api.nvidia.com/v1/chat/completions',
  extractor_model: 'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning',
  reasoning_model: 'nvidia/nemotron-3-ultra-550b-a55b',
  max_base64_chars: 4000000,
  confidence_threshold: 0.85
};
let analysis_eligible = true;
let eligibility_reason = 'eligible';
if (!allowed.includes(mime)) { analysis_eligible = false; eligibility_reason = 'PILOT_SUPPORTS_ONLY_JPEG_PNG'; }
else if (!base64) { analysis_eligible = false; eligibility_reason = 'MISSING_BINARY_CONTENT'; }
else if (base64.length > config.max_base64_chars) { analysis_eligible = false; eligibility_reason = 'IMAGE_REQUIRES_PREPROCESSING'; }
return [{ json: { ...doc, ai_config: config, analysis_eligible, eligibility_reason, ai_started_at: new Date().toISOString() } }];

const response = $input.first().json;
const original = $('Configurar adaptador e validar mídia').first().json;
const content = response.choices?.[0]?.message?.content ?? response.output_text ?? response.text ?? '';
if (!content) throw new Error('NVIDIA_EXTRACTOR_EMPTY_RESPONSE');
return [{ json: { ...original, ocr_text: typeof content === 'string' ? content : JSON.stringify(content), extractor_request_id: response.id ?? '', extractor_usage: response.usage ?? {} } }];

const item = $input.first().json;
const prompt = [
  'Você é um extrator de documentos fiscais brasileiros. Responda SOMENTE JSON válido, sem markdown.',
  'Nunca invente valores. Use null quando não houver evidência.',
  'Schema: {document_type, issuer_name, issuer_cnpj, recipient_name, recipient_cnpj, document_number, series, issue_date, access_key, total_amount, currency, confidence, evidence, warnings}.',
  'confidence deve estar entre 0 e 1. evidence deve citar trechos literais do OCR por campo.',
  'OCR:', item.ocr_text
].join('\n');
return [{ json: { ...item, reasoning_prompt: prompt } }];

const response = $input.first().json;
const original = $('Preparar raciocínio Nemotron').first().json;
let raw = response.choices?.[0]?.message?.content ?? response.output_text ?? '';
raw = String(raw).trim().replace(/^\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60$/i, '').trim();
let parsed;
let invalidJson = false;
try { parsed = JSON.parse(raw); } catch { parsed = {}; invalidJson = true; }
const digits = (v) => String(v ?? '').replace(/\D/g, '');
const warnings = Array.isArray(parsed.warnings) ? [...parsed.warnings] : [];
if (invalidJson) warnings.push('MODEL_OUTPUT_INVALID_JSON');
if (!parsed.document_type) warnings.push('MISSING_DOCUMENT_TYPE');
if (!parsed.issuer_name && digits(parsed.issuer_cnpj).length !== 14) warnings.push('MISSING_ISSUER');
if (!parsed.document_number) warnings.push('MISSING_DOCUMENT_NUMBER');
if (parsed.access_key && digits(parsed.access_key).length !== 44) warnings.push('INVALID_ACCESS_KEY');
if (parsed.issuer_cnpj && digits(parsed.issuer_cnpj).length !== 14) warnings.push('INVALID_ISSUER_CNPJ');
const confidence = Number(parsed.confidence ?? 0);
const reviewRequired = warnings.length > 0 || !Number.isFinite(confidence) || confidence < original.ai_config.confidence_threshold;
const finished = new Date();
const started = new Date(original.ai_started_at);
const normalized = { ...parsed, warnings, confidence: Number.isFinite(confidence) ? confidence : 0 };
return [{ json: {
  ...original,
  document_type: normalized.document_type ?? 'unknown', status: reviewRequired ? 'REVIEW_REQUIRED' : 'AI_VALIDATED',
  review_required: reviewRequired, review_reason: warnings.join('|') || (reviewRequired ? 'LOW_CONFIDENCE' : ''),
  provider: original.ai_config.provider, model: original.ai_config.reasoning_model,
  provider_request_id: response.id ?? original.extractor_request_id ?? '', processing_ms: Math.max(0, finished - started),
  estimated_cost: 0, extracted_json: JSON.stringify({ normalized, ocr_text: original.ocr_text, usage: { extractor: original.extractor_usage, reasoning: response.usage ?? {} }, cost_status: 'CLIENT_BILLING_NOT_CONFIGURED' }),
  updated_at: finished.toISOString()
} }];
